import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SCHEMA_VERSION, migrateProject } from "../src/project-model/schema";
import { decodeShareCode, encodeShareCode } from "../src/export/shareCode";
import { createDefaultProject } from "../src/project-model/schema";

/**
 * COMPATIBILITY PROMISE — the pin (docs/COMPATIBILITY.md).
 *
 * A share code written in 2026 must still open years from now. That claim is
 * only worth something if it is TESTED against a committed artifact, so this
 * suite decodes a golden v1 share code generated by the encoder as it was on
 * 2026-10-17 and requires that it (a) decodes, (b) carries the recorded shape,
 * and (c) migrates to the CURRENT schema version.
 *
 * NEVER regenerate or delete the fixture to make this pass. A failure here is
 * the promise being broken, not a stale file.
 */

const FIXTURE_PATH = "tests/fixtures/compatibility/share-code-v1.json";

interface CompatibilityFixture {
  format: string;
  note: string;
  code: string;
  expected: {
    id: string;
    name: string;
    schemaVersion: number;
    bpm: number;
    trackCount: number;
    patternCount: number;
    trackKinds: string[];
  };
}

function readFixture(): CompatibilityFixture {
  return JSON.parse(readFileSync(FIXTURE_PATH, "utf8")) as CompatibilityFixture;
}

describe("compatibility — a v1 share code keeps opening", () => {
  it("decodes the committed golden fixture to the recorded shape", () => {
    const fixture = readFixture();
    expect(fixture.format).toBe("share-code.v1");

    const decoded = decodeShareCode(fixture.code);
    expect(decoded, "a committed v1 share code must decode").not.toBeNull();
    expect(decoded!.id).toBe(fixture.expected.id);
    expect(decoded!.name).toBe(fixture.expected.name);
    expect(decoded!.bpm).toBe(fixture.expected.bpm);
    expect(decoded!.tracks).toHaveLength(fixture.expected.trackCount);
    expect(decoded!.patterns).toHaveLength(fixture.expected.patternCount);
    expect(decoded!.tracks.map((track) => track.kind)).toEqual(fixture.expected.trackKinds);
  });

  it("migrates the old code forward to the CURRENT schema version", () => {
    const fixture = readFixture();
    const decoded = decodeShareCode(fixture.code)!;
    // The fixture was written at an older (or equal) schema version; whichever
    // it is, the migration path must land on today's version.
    expect(fixture.expected.schemaVersion).toBeLessThanOrEqual(SCHEMA_VERSION);

    const migrated = migrateProject(structuredClone(decoded));
    expect(migrated.schemaVersion).toBe(SCHEMA_VERSION);
    expect(migrated.id).toBe(fixture.expected.id);
  });

  it("still REFUSES a project from the future (the other half of the promise)", () => {
    const fixture = readFixture();
    const fromTheFuture = structuredClone(decodeShareCode(fixture.code)!);
    (fromTheFuture as { schemaVersion: number }).schemaVersion = SCHEMA_VERSION + 1;
    expect(() => migrateProject(fromTheFuture)).toThrow(/newer than supported/i);
  });

  it("round-trips a fresh project through the same encode/decode path", () => {
    const doc = createDefaultProject();
    const decoded = decodeShareCode(encodeShareCode(doc));
    expect(decoded?.id).toBe(doc.id);
    expect(decoded?.schemaVersion).toBe(doc.schemaVersion);
  });
});
